import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { render, screen } from '@testing-library/react';

import { BracketTreeTV } from '../components/BracketTreeTV';
import { buildColumns, fitScale, isGeneratedBye } from '../bracketLayout';
import type { PublicMatch, PublicRound, PublicTeam } from '../types';

/**
 * The TV tree leaves a draw's generated byes out — 35 pairs in a 64 draw is 29 bye "matches" and
 * 3 real ones, and as cards they made the first round the tallest column on a screen with no
 * scrollbar. What must hold: a bye is only the one-sided auto walkover, the real first-round
 * matches stay and sit in the row of the match they feed, and a draw that cannot be laid out that
 * way is shown as it is rather than with a match missing.
 */

class StubResizeObserver {
    observe(): void {}
    unobserve(): void {}
    disconnect(): void {}
}

beforeEach(() => {
    vi.stubGlobal('ResizeObserver', StubResizeObserver);
});

afterEach(() => {
    vi.unstubAllGlobals();
});

function team(name: string): PublicTeam {
    return { team_name: name, player_1: null, player_2: null, is_lucky_loser: null };
}

function match(id: string, teamA: string | null, teamB: string | null, over: Partial<PublicMatch> = {}): PublicMatch {
    return {
        id, match_label: null, round_number: 1,
        team_a: teamA ? team(teamA) : null, team_b: teamB ? team(teamB) : null,
        sets: [], winner_team: null, next_match_id: null,
        status: 'not_scheduled', court_name: null, scheduled_at: null,
        ...over,
    };
}

function bye(id: string, seed: string, next: string): PublicMatch {
    return match(id, seed, null, { status: 'walkover', winner_team: 'team_a', next_match_id: next });
}

function round(number: number, name: string, matches: PublicMatch[]): PublicRound {
    return { round_number: number, round_name: name, matches };
}

/** Five pairs in an eight draw: seeds 1–3 get byes, 4 v 5 is the one real first-round match. */
function fivePairDraw(): PublicRound[] {
    return [
        round(1, 'Round 1', [
            bye('r1a', 'Seed 1', 'sf1'),
            match('r1b', 'Seed 4', 'Seed 5', { next_match_id: 'sf1' }),
            bye('r1c', 'Seed 3', 'sf2'),
            bye('r1d', 'Seed 2', 'sf2'),
        ]),
        round(2, 'Semifinal', [
            match('sf1', 'Seed 1', null, { round_number: 2, next_match_id: 'f' }),
            match('sf2', 'Seed 3', 'Seed 2', { round_number: 2, next_match_id: 'f' }),
        ]),
        round(3, 'Final', [match('f', null, null, { round_number: 3 })]),
    ];
}

const ids = (slots: (PublicMatch | null)[]): (string | null)[] => slots.map(m => m?.id ?? null);

describe('isGeneratedBye', () => {
    it('is the one-sided auto walkover', () => {
        expect(isGeneratedBye(bye('b', 'Seed 1', 'n'))).toBe(true);
    });

    it('is not a walkover between two pairs — a withdrawal stays on the board', () => {
        expect(isGeneratedBye(match('w', 'A', 'B', { status: 'walkover', winner_team: 'team_a' }))).toBe(false);
    });

    it('is not a match still waiting for a side', () => {
        expect(isGeneratedBye(match('w', 'A', null))).toBe(false);
    });
});

describe('buildColumns', () => {
    it('drops the byes and puts the real first-round match in the row of the match it feeds', () => {
        const columns = buildColumns(fivePairDraw());
        expect(columns.map(c => c.key)).toEqual(['L1', 'L2', 'C', 'R2', 'R1']);
        expect(ids(columns[0].slots)).toEqual(['r1b']);
        // The right side's first round is all byes, but the round keeps its column so the final stays centred.
        expect(ids(columns[4].slots)).toEqual([null]);
        expect(ids(columns[1].slots)).toEqual(['sf1']);
    });

    it('keeps the byes when a next-round match is fed by two real matches', () => {
        const rounds = fivePairDraw();
        rounds[0].matches[0] = match('r1a', 'Seed 1', 'Seed 8', { next_match_id: 'sf1' });
        const columns = buildColumns(rounds);
        expect(ids(columns[0].slots)).toEqual(['r1a', 'r1b']);
        expect(ids(columns[4].slots)).toEqual(['r1c', 'r1d']);
    });

    it('leaves a two-round draw as it is: its first round feeds the final directly', () => {
        const rounds = [
            round(1, 'Semifinal', [bye('a', 'Seed 1', 'f'), match('b', 'Seed 2', 'Seed 3', { next_match_id: 'f' })]),
            round(2, 'Final', [match('f', null, null, { round_number: 2 })]),
        ];
        expect(buildColumns(rounds).map(c => ids(c.slots))).toEqual([['a'], ['f'], ['b']]);
    });
});

describe('fitScale', () => {
    it('shrinks a tree wider than the screen to the screen', () => {
        expect(fitScale({ width: 1600, height: 695 }, { width: 1752, height: 750 })).toBeCloseTo(1600 / 1752);
    });

    it('never enlarges a tree that already fits', () => {
        expect(fitScale({ width: 1600, height: 695 }, { width: 900, height: 400 })).toBe(1);
    });

    it('is 1 when nothing has been measured (jsdom)', () => {
        expect(fitScale({ width: 0, height: 0 }, { width: 0, height: 0 })).toBe(1);
    });
});

describe('BracketTreeTV with byes', () => {
    it('shows each pair given a bye once — in the round it was advanced to — and the real match', () => {
        render(<BracketTreeTV rounds={fivePairDraw()} />);
        expect(screen.getAllByText('Seed 1')).toHaveLength(1);
        expect(screen.getAllByText('Seed 2')).toHaveLength(1);
        expect(screen.getByText('Seed 4')).toBeInTheDocument();
        expect(screen.getByText('Seed 5')).toBeInTheDocument();
    });
});
